mapper.select:
SELECT u.id, u.email, u.nickname, r.code AS role, u.status, u.onboarding_completed AS onboardingCompleted, u.must_change_password AS mustChangePassword, u.created_at AS createdAt, u.last_login_at AS lastLoginAt FROM users u JOIN roles r ON r.id = u.role_id AND r.is_active = 1 WHERE r.code = 'USER'
AND u.email LIKE CONCAT(#{emailPrefix}, '%') ESCAPE '\\'
AND u.nickname LIKE CONCAT('%', #{nicknameContains}, '%') ESCAPE '\\'
AND u.status = #{status}
AND u.created_at >= #{registeredStartAt}
AND u.created_at < #{registeredEndExclusiveAt}
ORDER BY u.created_at DESC, u.id DESC

mapper.update:
UPDATE users
SET status = #{status},
    auth_version = auth_version + 1
WHERE id = #{userId}
  AND auth_version = #{expectedVersion}
  AND status IN ('ACTIVE', 'DISABLED')

UPDATE users
SET admin_login_name = #{adminLoginName},
    auth_version = auth_version + 1
WHERE id = #{userId}
  AND auth_version = #{expectedVersion}
  AND status = 'ACTIVE'
